(()=>{'use strict';function enhance(){const root=document.getElementById('ffhSoaRoot');if(!root)return;const results=root.querySelector('#soaResults');if(!results)return;const heading=results.querySelector('.soaTableHeading');if(!heading)return;const first=heading.firstChild;if(first&&first.nodeType===3&&first.textContent!=='☷ Transactions'){first.textContent='☷ Transactions';}
if(!heading.querySelector('.soaRefTools')){const tools=document.createElement('div');tools.className='soaRefTools';tools.style.cssText='display:flex;gap:5px;align-items:center;margin-left:auto';const search=document.createElement('button');search.type='button';search.textContent='⌕';search.title='Search invoice / reference';search.setAttribute('aria-label','Search transactions');const full=document.createElement('button');full.type='button';full.textContent='⛶';full.title='Fullscreen transactions';full.setAttribute('aria-label','Fullscreen transactions');for(const b of [search,full])b.style.cssText='border:1px solid #ff8500;border-radius:8px;background:#170b03;color:white;font-size:19px;padding:3px 9px';search.onclick=()=>{const input=results.querySelector('#soaSearch');if(input){input.closest('label')?.scrollIntoView({block:'nearest'});input.focus();input.select();}};full.onclick=()=>{results.classList.toggle('soaReferenceFullscreen');full.setAttribute('aria-pressed',String(results.classList.contains('soaReferenceFullscreen')))};tools.append(search,full);heading.insertBefore(tools,heading.querySelector('span'));}
}
const style=document.createElement('style');style.textContent='#ffhSoaRoot #soaResults.soaReferenceFullscreen{position:fixed!important;inset:8px!important;z-index:99999!important;min-height:0!important;height:calc(100dvh - 16px)!important;background:#080808!important}#ffhSoaRoot #soaResults.soaReferenceFullscreen #soaPrint{min-height:0!important}';document.head.append(style);let pending=false;new MutationObserver(()=>{if(pending)return;pending=true;queueMicrotask(()=>{pending=false;enhance()})}).observe(document.body,{childList:true,subtree:true});enhance();})();